DEFINE_LOG_CATEGORY_STATIC(LogPBXStory, Log, All);
#define SLOG(Fmt, ...) UE_LOG(LogPBXStory, Display, TEXT(Fmt), ##__VA_ARGS__)

using FJArr = TArray<TSharedPtr<FJsonValue>>;

static FString StoryPath(const FString& Ep) { return FPaths::ProjectContentDir() / TEXT("PBX/Story") / (Ep + TEXT(".json")); }

bool APBXDirector::HasStory(const FString& Ep) const { return !FParse::Param(FCommandLine::Get(), TEXT("pbxold")) && FPaths::FileExists(StoryPath(Ep)); }

bool APBXDirector::LoadStory(const FString& Ep)
{
	FString Txt;
	if (!FFileHelper::LoadFileToString(Txt, *StoryPath(Ep))) { SLOG("[PBXSTORY] missing %s", *StoryPath(Ep)); return false; }
	TSharedPtr<FJsonObject> O; const TSharedRef<TJsonReader<>> R = TJsonReaderFactory<>::Create(Txt);
	if (!FJsonSerializer::Deserialize(R, O) || !O.IsValid()) { SLOG("[PBXSTORY] bad json %s", *Ep); return false; }
	StoryData = O; StoryEp = Ep;
	FString P; if (FParse::Value(FCommandLine::Get(), TEXT("pbxpath="), P)) AutoPath = P;
	return true;
}

// ---------------------------------------------------------------- vars / text / speakers
bool APBXDirector::StoryCond(const FString& C) const
{
	if (C.TrimStartAndEnd().IsEmpty()) return true;
	TArray<FString> Ors; C.ParseIntoArray(Ors, TEXT("||"));
	for (const FString& Or : Ors)
	{
		TArray<FString> Ands; Or.ParseIntoArray(Ands, TEXT("&&")); bool bAll = true;
		for (FString T : Ands)
		{
			T.TrimStartAndEndInline(); const bool bNot = T.StartsWith(TEXT("!")) && !T.StartsWith(TEXT("!=")); if (bNot) T.RightChopInline(1);
			static const TCHAR* Ops[] = { TEXT(">="), TEXT("<="), TEXT("=="), TEXT("!="), TEXT(">"), TEXT("<") };
			int32 Op = -1, At = -1;
			for (int32 k = 0; k < 6; k++) { At = T.Find(Ops[k]); if (At > 0) { Op = k; break; } }
			bool R;
			if (Op < 0) R = SVar(T.TrimStartAndEnd()) != 0;
			else
			{
				const FString L = T.Left(At).TrimStartAndEnd(), Rs = T.Mid(At + FCString::Strlen(Ops[Op])).TrimStartAndEnd();
				const int32 a = SVar(L), b = Rs.IsNumeric() ? FCString::Atoi(*Rs) : SVar(Rs);
				switch (Op) { case 0: R = a >= b; break; case 1: R = a <= b; break; case 2: R = a == b; break; case 3: R = a != b; break; case 4: R = a > b; break; default: R = a < b; }
			}
			if (bNot) R = !R;
			if (!R) { bAll = false; break; }
		}
		if (bAll) return true;
	}
	return false;
}

FString APBXDirector::StoryText(const FString& In) const
{
	FString T = In;
	const bool bMale = !Game || !Game->State || Game->State->bMale;
	T.ReplaceInline(TEXT("{hero}"), bMale ? TEXT("Rook") : TEXT("Vesna"));
	T.ReplaceInline(TEXT("{lad}"), bMale ? TEXT("lad") : TEXT("girl"));
	T.ReplaceInline(TEXT("{he}"), bMale ? TEXT("he") : TEXT("she"));
	static const TCHAR* Sparks[] = { TEXT("your Spark"), TEXT("Cindril"), TEXT("Glublet"), TEXT("Sporrow") };
	T.ReplaceInline(TEXT("{spark}"), Sparks[FMath::Clamp(SVar(TEXT("partner")), 0, 3)]);
	return T;
}

FString APBXDirector::StorySpeaker(const FString& Who, FLinearColor& OutColor) const
{
	OutColor = FLinearColor(1, .82f, .2f);
	if (Who == TEXT("narrator")) { OutColor = FLinearColor(.85f, .82f, .75f); return FString(); }
	if (Who == TEXT("hero")) { OutColor = FLinearColor(.95f, .9f, .8f); return StoryText(TEXT("{hero}")); }
	if (Who == TEXT("spark")) { OutColor = FLinearColor(.75f, .1f, .12f); return StoryText(TEXT("{spark}")) + TEXT(" (writes)"); }
	if (Who == TEXT("codex")) { OutColor = FLinearColor(.6f, .55f, .45f); return TEXT("Codex"); }
	const TSharedPtr<FJsonObject>* Cast_;
	if (StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("cast"), Cast_))
	{
		const TSharedPtr<FJsonObject>* C;
		if ((*Cast_)->TryGetObjectField(Who, C))
		{
			const TArray<TSharedPtr<FJsonValue>>* Col; if ((*C)->TryGetArrayField(TEXT("color"), Col) && Col->Num() >= 3) OutColor = FLinearColor((*Col)[0]->AsNumber(), (*Col)[1]->AsNumber(), (*Col)[2]->AsNumber());
			return (*C)->GetStringField(TEXT("name"));
		}
	}
	return SpeakerName(FName(*Who));
}

FVector APBXDirector::StoryAt(const FString& At) const
{
	// "npc:rho" (where that person stands) · "spot:<id>" (a map spot) · "x,y,z"
	if (At.StartsWith(TEXT("npc:"))) { FString Id = At.Mid(4); if (const TSharedPtr<FJsonObject>* Cast_; StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("cast"), Cast_)) { const TSharedPtr<FJsonObject>* C; if ((*Cast_)->TryGetObjectField(Id, C)) (*C)->TryGetStringField(TEXT("npc"), Id); } if (const TObjectPtr<APBXNPC>* N = NPCs.Find(FName(*Id))) return (*N)->GetActorLocation(); return FVector::ZeroVector; }
	if (At.StartsWith(TEXT("spot:"))) { if (const FPBXSpot* S = Spots.Find(At.Mid(5))) return S->Pos; return FVector::ZeroVector; }
	if (At.StartsWith(TEXT("stage:")))   // "stage:<Name>:x,y,z" — a point on a v4 set (origin from the episode's "stages")
	{
		TArray<FString> Parts; At.ParseIntoArray(Parts, TEXT(":"));
		FVector O = FVector::ZeroVector; const TSharedPtr<FJsonObject>* St; const TArray<TSharedPtr<FJsonValue>>* A;
		if (Parts.Num() >= 2 && StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("stages"), St) && (*St)->TryGetArrayField(Parts[1], A) && A->Num() >= 3)
			O = FVector((*A)[0]->AsNumber(), (*A)[1]->AsNumber(), (*A)[2]->AsNumber());
		FVector L = FVector::ZeroVector;
		if (Parts.Num() >= 3) { TArray<FString> P; Parts[2].ParseIntoArray(P, TEXT(",")); if (P.Num() >= 3) L = FVector(FCString::Atof(*P[0]), FCString::Atof(*P[1]), FCString::Atof(*P[2])); }
		return O + L + FVector(0, 0, .01f);
	}
	TArray<FString> P; At.ParseIntoArray(P, TEXT(","));
	return P.Num() >= 3 ? FVector(FCString::Atof(*P[0]), FCString::Atof(*P[1]), FCString::Atof(*P[2])) : FVector::ZeroVector;
}

// Staging on the v4 sets: the authored stage points are rough; a ground trace from above lands people on stall roofs and
// crates (the hero stood 3.3 m up on the pier and every shot framed the sky or a wall). Ring search outward for floor
// within 45 cm of the stage point's height where a standing capsule is free.
FVector APBXDirector::StoryFloor(const FVector& Want, const AActor* Ignore) const
{
	UWorld* W = GetWorld(); if (!W) return Want;
	FCollisionQueryParams Q(SCENE_QUERY_STAT(StoryFloor), false);
	for (TActorIterator<ACharacter> It(W); It; ++It) Q.AddIgnoredActor(*It);   // people don't block (they get placed too)
	for (int32 r = 0; r <= 14; r++)
		for (int32 k = 0; k < (r == 0 ? 1 : 16); k++)
		{
			const float A = k * 2.f * PI / 16.f; const FVector P = Want + FVector(FMath::Cos(A), FMath::Sin(A), 0.f) * (r * 45.f);
			FHitResult H;
			if (!W->LineTraceSingleByChannel(H, P + FVector(0, 0, 60.f), P - FVector(0, 0, 160.f), ECC_Visibility, Q)) continue;   // start BELOW roofs
			if (FMath::Abs(H.Location.Z - Want.Z) > 45.f) continue;
			const FVector C = H.Location + FVector(0, 0, 98.f);
			if (W->OverlapAnyTestByChannel(C, FQuat::Identity, ECC_Pawn, FCollisionShape::MakeCapsule(36.f, 88.f), Q)) continue;
			// a clear head: nothing between the floor and 2.1 m (awnings, beams)
			if (W->LineTraceTestByChannel(H.Location + FVector(0, 0, 20.f), H.Location + FVector(0, 0, 210.f), ECC_Visibility, Q)) continue;
			return H.Location;
		}
	SLOG("[PBXSTORY] no floor near %s", *Want.ToCompactString());
	return Want;
}

// ---------------------------------------------------------------- flow
void APBXDirector::StoryBegin(const FString& Ep, const FString& Scene, bool bFromSave)
{
	if (!LoadStory(Ep)) { Toast(TEXT("Story file missing.")); return; }
	bStoryMode = true; AutoChoice = 0; Music(TEXT("")); MusicHold = 1e9f;   // the story drives the music
	const FString Start = Scene.IsEmpty() ? StoryData->GetStringField(TEXT("start")) : Scene;
	if (bFromSave && Game && Game->State) SVars = Game->State->StoryVars; else SVars.Reset();
	if (!bFromSave && Game && Game->State) Game->State->StoryChoices.Reset();
	SLOG("[PBXSTORY] begin %s at %s (%s)", *Ep, *Start, bFromSave ? TEXT("save") : TEXT("new"));
	StoryGoto(Start);
	QStoryPump();
}

void APBXDirector::StoryGoto(const FString& Scene)
{
	const TSharedPtr<FJsonObject>* Scenes; const TSharedPtr<FJsonObject>* S;
	if (!StoryData->TryGetObjectField(TEXT("scenes"), Scenes) || !(*Scenes)->TryGetObjectField(Scene, S)) { SLOG("[PBXSTORY] ERROR no scene %s", *Scene); Toast(TEXT("Missing scene: ") + Scene); return; }
	StoryScene = Scene; SStack.Reset(); HubSpots.Reset(); bHub = false; StoryCamRelease(); ShotOther = nullptr;
	UI->PageInk = 0.f; UI->PageSeed = GetTypeHash(Scene);   // a new page: the ink blots back over the next 1.4 s
	FStoryFrame F; F.Nodes = (*S)->GetArrayField(TEXT("nodes")); SStack.Add(F);
	UI->Chapter = (*S)->GetStringField(TEXT("title"));
	// autosave at the start of every scene: the vars as they were when the scene began (a reload replays the scene)
	if (Game && Game->State) { Game->State->StoryEp = StoryEp; Game->State->StoryScene = Scene; Game->State->StoryVars = SVars; if (!bAuto) SaveNow(false); }
	SLOG("[PBXSTORY] scene %s", *Scene);
}

void APBXDirector::QStoryPump() { Q([this](float) { StoryPump(); return true; }); }

void APBXDirector::StoryPush(const FJArr* Nodes)
{
	if (!Nodes || !Nodes->Num()) return;
	FStoryFrame F; F.Nodes = *Nodes; SStack.Add(F);
}

void APBXDirector::StoryPump()
{
	int32 Guard = 0;
	while (SStack.Num() && Guard++ < 2000)
	{
		FStoryFrame& Fr = SStack.Last();
		if (Fr.I >= Fr.Nodes.Num()) { SStack.Pop(); continue; }
		const TSharedPtr<FJsonObject> N = Fr.Nodes[Fr.I++]->AsObject();
		if (!N.IsValid()) continue;
		FString S; double D = 0;
		// --- instant nodes
		if (N->TryGetStringField(TEXT("set"), S)) { SVars.Add(S, N->HasField(TEXT("v")) ? (int32)N->GetNumberField(TEXT("v")) : 1); continue; }
		if (N->TryGetStringField(TEXT("unset"), S)) { SVars.Remove(S); continue; }
		if (N->TryGetStringField(TEXT("add"), S)) { SVars.Add(S, SVar(S) + (N->HasField(TEXT("v")) ? (int32)N->GetNumberField(TEXT("v")) : 1)); continue; }
		const TSharedPtr<FJsonObject>* Rel;
		if (N->TryGetObjectField(TEXT("rel"), Rel)) { for (const auto& KV : (*Rel)->Values) { const FString K(KV.Key); SVars.Add(K, FMath::Clamp(SVar(K) + (int32)KV.Value->AsNumber(), -5, 5)); } continue; }
		if (N->TryGetStringField(TEXT("toast"), S)) { Toast(StoryText(S)); continue; }
		if (N->TryGetStringField(TEXT("objective"), S)) { UI->Objective = StoryText(S); continue; }
		if (N->TryGetStringField(TEXT("sfx"), S))
		{
			if (PBXAudio::Exists(TEXT("sfx"), S)) { if (USoundWaveProcedural* W = PBXAudio::Load(this, TEXT("sfx"), S, false)) { UGameplayStatics::SpawnSound2D(this, W, .8f * VolSfx); FilmCue(TEXT("sfx"), S, .8f); } }
			else Sfx(*S);
			continue;
		}
		if (N->TryGetStringField(TEXT("music"), S))
		{
			double Fade = 2.5; N->TryGetNumberField(TEXT("xfade"), Fade);
			if (S.IsEmpty() || PBXAudio::Exists(TEXT("music"), S)) { Music(TEXT("")); MusicHold = 9999.f; StoryLoop(StoryMusic, StoryMusicName, TEXT("music"), S, .38f * VolMusic, Fade); }
			else { Music(*S); MusicHold = 9999.f; }
			continue;
		}
		if (N->TryGetStringField(TEXT("amb"), S)) { StoryLoop(StoryAmb, StoryAmbName, TEXT("amb"), S, .55f * VolSfx, 2.0f); continue; }
		bool bB; if (N->TryGetBoolField(TEXT("blanked"), bB)) { ApplyBlanked(bB); continue; }
		if (N->TryGetStringField(TEXT("npc"), S))   // put a cast member somewhere: {"npc": "rho", "at": "stage:Pier:700,800,0", "yaw": 200}
		{
			if (APBXNPC* A = Cast<APBXNPC>(StoryActor(S)))
			{
				FString At; N->TryGetStringField(TEXT("at"), At); double Yaw = 0; N->TryGetNumberField(TEXT("yaw"), Yaw);
				const FVector L = StoryAt(At);
				if (!NpcHome.Contains(A)) NpcHome.Add(A, A->GetActorTransform());
				if (!L.IsZero())
				{
					FVector F;
					if (At.StartsWith(TEXT("stage:"))) F = StoryFloor(L, A);
					else F = FVector(L.X, L.Y, PBXWorld::GroundZ(GetWorld(), L, 200.f, 1200.f, L.Z));
					A->SetActorLocationAndRotation(F + FVector(0, 0, 92.f), FRotator(0, Yaw, 0), false, nullptr, ETeleportType::TeleportPhysics);
				}
			}
			else SLOG("[PBXSTORY] npc: no actor for %s", *S);
			continue;
		}
		bool bHome; if (N->TryGetBoolField(TEXT("npc_home"), bHome))   // everyone the story moved goes back to where the town keeps them
		{
			for (auto& KV : NpcHome) if (KV.Key.IsValid()) KV.Key->SetActorTransform(KV.Value, false, nullptr, ETeleportType::TeleportPhysics);
			NpcHome.Reset(); continue;
		}
		const TSharedPtr<FJsonObject>* SunO;
		if (N->TryGetObjectField(TEXT("sun"), SunO))   // time of day per scene: {"sun": {"pitch": -8, "yaw": 250, "k": .7, "color": [1,.55,.35]}}
		{
			double Pitch = -35, Yaw = 35, K = 1; (*SunO)->TryGetNumberField(TEXT("pitch"), Pitch); (*SunO)->TryGetNumberField(TEXT("yaw"), Yaw); (*SunO)->TryGetNumberField(TEXT("k"), K);
			// night (k <= .15): the sun goes under the horizon so the sky atmosphere and the clouds go dark (a lamp room at
			// night showed a daytime sky), the sky light drops and the fog turns night blue; any other sun restores them
			const bool bNight = K <= .15;
			for (TActorIterator<ASkyLight> It(GetWorld()); It; ++It) if (USkyLightComponent* SC = It->GetLightComponent())
			{ if (MoodBack.bSky) SC->SetIntensity(MoodBack.SkyI * (bNight ? .35f : 1.f)); break; }
			for (TActorIterator<AExponentialHeightFog> It(GetWorld()); It; ++It) if (UExponentialHeightFogComponent* FC = It->GetComponent())
			{ FC->SetFogInscatteringColor(bNight ? FLinearColor(.05f, .06f, .10f) : FLinearColor(.40f, .42f, .47f)); break; }
			if (bNight) Pitch = 12.0;
			for (TActorIterator<ADirectionalLight> It(GetWorld()); It; ++It) if (ULightComponent* LC = It->GetLightComponent())
			{
				It->SetActorRotation(FRotator(Pitch, Yaw, 0));
				if (MoodBack.bSun) LC->SetIntensity(MoodBack.SunI * K);
				const TArray<TSharedPtr<FJsonValue>>* Col; if ((*SunO)->TryGetArrayField(TEXT("color"), Col) && Col->Num() >= 3) LC->SetLightColor(FLinearColor((*Col)[0]->AsNumber(), (*Col)[1]->AsNumber(), (*Col)[2]->AsNumber()));
				break;
			}
			continue;
		}
		if (N->TryGetStringField(TEXT("place"), S))   // where the scene is staged: "door:<id>:in|out", "spot:<id>", "npc:<id>"
		{
			FPBXSpot P; bool bOk = false; bool bFloorPlace = false;
			{	// video sets (owner 2026-11-08): on a stage the old town's mountain ring and foliage would float in the sky
				// around the set → everything tagged PBX_Town (pbx_harbour.tag_town) hides while the scene is on a stage
				const bool bStage = S.StartsWith(TEXT("stage:"));
				for (TActorIterator<AActor> It(GetWorld()); It; ++It) if (It->ActorHasTag(TEXT("PBX_Town"))) It->SetActorHiddenInGame(bStage);
			}
			if (S.StartsWith(TEXT("door:")))
			{
				TArray<FString> Parts; S.ParseIntoArray(Parts, TEXT(":"));
				for (const FPBXDoor& Dr : Doors) if (Parts.Num() >= 2 && Dr.Id == Parts[1]) { P = (Parts.Num() > 2 && Parts[2] == TEXT("in")) ? Dr.Inside : Dr.Outside; bOk = true; }
			}
			else if (S.StartsWith(TEXT("spot:"))) { if (const FPBXSpot* Sp = Spots.Find(S.Mid(5))) { P = *Sp; bOk = true; } }
			else if (S.StartsWith(TEXT("stage:"))) { TArray<FString> Parts; S.ParseIntoArray(Parts, TEXT(":")); P.Pos = StoryFloor(StoryAt(S), Player) + FVector(0, 0, 5); P.Yaw = Parts.Num() >= 4 ? FCString::Atof(*Parts[3]) : 0.f; bOk = true; bFloorPlace = true; }
			else { const FVector At = StoryAt(S); if (!At.IsZero()) { P.Pos = At + FVector(180, 0, 0); P.Yaw = 180.f; bOk = true; } }
			if (bOk) PlacePlayer(P); else SLOG("[PBXSTORY] place: unknown %s", *S);
			if (bOk && bFloorPlace && Player) Player->SetActorLocation(P.Pos + FVector(0, 0, 90.f), false, nullptr, ETeleportType::TeleportPhysics);   // PlacePlayer's ground trace from above would pick a roof
			continue;
		}
		if (N->TryGetStringField(TEXT("log"), S)) { SLOG("[PBXSTORY] %s", *S); continue; }
		if (N->TryGetStringField(TEXT("if"), S))
		{
			const FJArr* Br = nullptr; const bool bOk = StoryCond(S);
			N->TryGetArrayField(bOk ? TEXT("then") : TEXT("else"), Br); StoryPush(Br); continue;
		}
		if (N->TryGetStringField(TEXT("goto"), S)) { StoryGoto(S); continue; }
		const TArray<TSharedPtr<FJsonValue>>* Fl;
		if (N->TryGetArrayField(TEXT("flash"), Fl) && Fl->Num() >= 3) { UI->FlashColor = FLinearColor((*Fl)[0]->AsNumber(), (*Fl)[1]->AsNumber(), (*Fl)[2]->AsNumber()); UI->FlashT = 1.2f; continue; }
		// --- nodes that take time: queue them, then come back here
		if (N->TryGetStringField(TEXT("say"), S))
		{
			FLinearColor C; const FString Name = StorySpeaker(S, C); const FString Line = StoryText(N->GetStringField(TEXT("line")));
			FString Vo; N->TryGetStringField(TEXT("vo"), Vo);
			if (!Vo.IsEmpty())
			{
				// variants: _m / _f for lines that name the hero, _p1.._p3 for lines that name the Spark
				bool bG = false, bS = false; N->TryGetBoolField(TEXT("vg"), bG); N->TryGetBoolField(TEXT("vs"), bS);
				if (bG) Vo += (!Game || !Game->State || Game->State->bMale) ? TEXT("_m") : TEXT("_f");
				if (bS) Vo += FString::Printf(TEXT("_p%d"), FMath::Clamp(SVar(TEXT("partner")), 1, 3));
			}
			FString ClipId; N->TryGetStringField(TEXT("vo"), ClipId);
			QDo([this, S, Vo, Line, ClipId] { const float Secs = Vo.IsEmpty() ? 0.f : StoryVoicePlay(Vo);
				if (!StoryFilm(ClipId)) { StoryShot(S); StoryAct(S, Line, Secs > 0.f ? Secs : 1.2f + Line.Len() * .055f); }
				if (APBXCharacterBase* C = Cast<APBXCharacterBase>(StoryActor(S))) C->Speak(Vo); });
			// QSay shows SpeakerName(Who): pass the resolved name through the "story" speaker slot
			StorySpeakerName = Name; StorySpeakerColor = C;
			QSay({ { FName(TEXT("__story")), Line } });
			LastLine = Name.IsEmpty() ? Line : Name + TEXT(":  ") + Line;
			QStoryPump(); return;
		}
		if (N->TryGetNumberField(TEXT("wait"), D)) { QWait(D); QStoryPump(); return; }
		if (N->TryGetNumberField(TEXT("fade"), D)) { double Secs = .6; N->TryGetNumberField(TEXT("secs"), Secs); QFade(D, Secs); QStoryPump(); return; }
		if (N->TryGetStringField(TEXT("title"), S))
		{
			FString Sub; N->TryGetStringField(TEXT("sub"), Sub); Splash(StoryText(S), StoryText(Sub), 3.2f);
			if (bAuto) { const FString Shot_ = FString::Printf(TEXT("st_%s"), *StoryScene); QDo([this, Shot_] { Shot(Shot_); }); }
			QWait(2.6f); QStoryPump(); return;
		}
		if (N->TryGetStringField(TEXT("panel"), S))
		{
			// drawn close-up panels (P2 makes the art; until then the panel's description is shown as a caption)
			const FString Cap = StoryText(S);
			QDo([this, Cap] { UI->Letterbox = 1.f; UI->Caption = TEXT("~"); UI->CaptionSub = Cap; UI->CaptionA = 1.f; });
			QWait(bAuto ? .8f : 2.4f);
			QDo([this] { UI->Letterbox = 0.f; UI->Caption.Empty(); UI->CaptionSub.Empty(); UI->CaptionA = 0.f; });
			QStoryPump(); return;
		}
		const TSharedPtr<FJsonObject>* Sub;
		if (N->HasField(TEXT("choice"))) { StoryChoice(N); return; }
		if (N->TryGetObjectField(TEXT("pact"), Sub)) { StoryPact(*Sub); return; }
		if (N->TryGetObjectField(TEXT("hub"), Sub))
		{
			Fr.I--;   // a hub stays the current node until its exit condition holds
			if (StoryHub(*Sub)) { Fr.I++; continue; }
			return;
		}
		if (N->HasField(TEXT("end"))) { StoryEndEpisode(); return; }
		SLOG("[PBXSTORY] WARNING unknown node in %s", *StoryScene);
	}
	if (!SStack.Num()) SLOG("[PBXSTORY] story stack empty in %s (no goto / end)", *StoryScene);
}

// ---------------------------------------------------------------- choices
void APBXDirector::StoryChoice(const TSharedPtr<FJsonObject>& N)
{
	const FString Prompt = StoryText(N->GetStringField(TEXT("choice")));
	double T = 0; N->TryGetNumberField(TEXT("t"), T);
	TSharedPtr<TArray<TSharedPtr<FJsonObject>>> Opts = MakeShared<TArray<TSharedPtr<FJsonObject>>>();
	TArray<FPBXOption> UIOpts;
	for (const TSharedPtr<FJsonValue>& V : N->GetArrayField(TEXT("opts")))
	{
		const TSharedPtr<FJsonObject> O = V->AsObject(); FString C; O->TryGetStringField(TEXT("if"), C);
		if (!StoryCond(C)) continue;
		Opts->Add(O);
		FPBXOption X; X.Title = StoryText(O->GetStringField(TEXT("text"))); X.Key = FString::FromInt(Opts->Num());
		FString Hint; if (O->TryGetStringField(TEXT("hint"), Hint)) X.Sub = Hint;
		UIOpts.Add(X);
	}
	FString Id; N->TryGetStringField(TEXT("id"), Id);
	const FString Scene = StoryScene;
	auto Pick = [this, Opts, N, Id, Scene](int32 i)
	{
		CloseChoice(); UI->FuseMax = UI->FuseT = 0.f; UI->bStoryChoice = false; OnFuse = nullptr;
		const FJArr* Do = nullptr; FString Text = TEXT("(silence)");
		if (Opts->IsValidIndex(i)) { (*Opts)[i]->TryGetArrayField(TEXT("do"), Do); Text = (*Opts)[i]->GetStringField(TEXT("text")); }
		else N->TryGetArrayField(TEXT("silent"), Do);
		if (!Id.IsEmpty() && Game && Game->State) Game->State->StoryChoices.Add(Id + TEXT("=") + (Opts->IsValidIndex(i) ? FString::FromInt(i) : TEXT("s")));
		SLOG("[PBXSTORY] choice %s:%s -> %d %s", *Scene, *Id, i, *Text);
		FilmCue(TEXT("pick"), Id, 1.f, FString::Printf(TEXT("\"i\":%d"), i));
		StoryPush(Do); QStoryPump();
	};
	if (UIOpts.Num() == 0) { SLOG("[PBXSTORY] ERROR choice %s with no eligible option", *Id); Pick(-1); return; }
	OpenChoice(TEXT(""), Prompt.IsEmpty() ? LastLine : Prompt, UIOpts, false, Pick);
	UI->bStoryChoice = true;
	{ FString Os; for (const FPBXOption& O : UIOpts) Os += (Os.IsEmpty() ? TEXT("\"") : TEXT(",\"")) + O.Title.Replace(TEXT("\""), TEXT("'")) + TEXT("\""); FilmCue(TEXT("choice"), Id, 1.f, TEXT("\"opts\":[") + Os + TEXT("]")); }
	if (T > 0) { UI->FuseMax = UI->FuseT = T; OnFuse = [Pick] { Pick(-1); }; }
	if (bAuto)   // the path digit for this choice (9 = let the fuse burn out)
	{
		const int32 Idx = AutoChoice++; int32 k = AutoPath.IsValidIndex(Idx) ? AutoPath[Idx] - '0' : 0;
		if (k == 9 && T <= 0) k = 0;
		if (k != 9) { k = FMath::Clamp(k, 0, UIOpts.Num() - 1); Q([this, Pick, k](float t) { if (t < .6f) return false; Pick(k); return true; }); }
		if (AutoShots < 400) Shot(FString::Printf(TEXT("ch_%s_%02d"), *StoryScene, Idx));
	}
}

void APBXDirector::StoryFuseTick(float Dt)
{
	if (UI->FuseMax <= 0.f || UI->Mode != EPBXUIMode::Choice) return;
	UI->FuseT -= Dt;
	if (UI->FuseT <= 0.f) { UI->FuseT = UI->FuseMax = 0.f; if (OnFuse) { TFunction<void()> F = OnFuse; OnFuse = nullptr; F(); } }
}

// ---------------------------------------------------------------- pact moments (fail forward)
void APBXDirector::StoryPact(const TSharedPtr<FJsonObject>& N)
{
	double Steps = 3, Window = 1.8; N->TryGetNumberField(TEXT("steps"), Steps); N->TryGetNumberField(TEXT("window"), Window);
	FString Prompt = TEXT("WRITE THE GLYPH"); N->TryGetStringField(TEXT("prompt"), Prompt);
	struct FPact { int32 Step = 0, Hits = 0, N = 3; float W = 1.8f, T0 = 0.f; bool bArmed = false; };
	TSharedPtr<FPact> P = MakeShared<FPact>(); P->N = (int32)Steps; P->W = (float)Window;
	const bool bAutoWin = !FParse::Param(FCommandLine::Get(), TEXT("pbxpactfail"));
	Q([this, P, N, Prompt, bAutoWin](float T)
	{
		if (!P->bArmed) { P->bArmed = true; P->T0 = T + .8f; bConfirm = false; UI->Letterbox = 1.f; Sfx(TEXT("ui_page")); }
		const float L = T - P->T0;
		if (L < 0.f) { Splash(Prompt, TEXT("get ready…"), .3f); bConfirm = false; return false; }
		const float W = P->W, Ls = L - P->Step * (W + .35f);
		if (Ls < 0.f) { bConfirm = false; return false; }   // the gap between strokes
		const int32 Left = FMath::CeilToInt(FMath::Max(0.f, W - Ls) * 4.f);
		Splash(FString::Printf(TEXT("CLICK  ·  STROKE %d / %d"), P->Step + 1, P->N), FString::ChrN(Left, TEXT('|')), .3f);
		if (bAuto && bAutoWin && Ls > W * .4f) bConfirm = true;
		if (bConfirm || Ls >= W)
		{
			if (bConfirm) { P->Hits++; Sfx(TEXT("sfx_confirm")); UI->FlashColor = FLinearColor(.75f, .1f, .1f); UI->FlashT = .35f; }
			else { UI->ShakeT = .4f; }
			bConfirm = false; P->Step++;
			if (P->Step >= P->N)
			{
				const bool bWin = P->Hits >= P->N - (P->N > 3 ? 1 : 0);   // one miss allowed in long sequences
				UI->Letterbox = 0.f; UI->BigT = 0.f;
				SLOG("[PBXSTORY] pact %s %d/%d -> %s", *StoryScene, P->Hits, P->N, bWin ? TEXT("win") : TEXT("lose"));
				const FJArr* Br = nullptr; N->TryGetArrayField(bWin ? TEXT("win") : TEXT("lose"), Br); StoryPush(Br); QStoryPump();
				return true;
			}
		}
		return false;
	});
}

// ---------------------------------------------------------------- hubs (walk, look, talk)
bool APBXDirector::StoryHub(const TSharedPtr<FJsonObject>& N)
{
	FString Exit; N->TryGetStringField(TEXT("exit"), Exit);
	FString Obj; if (N->TryGetStringField(TEXT("objective"), Obj)) UI->Objective = StoryText(Obj);
	HubSpots.Reset();
	for (const TSharedPtr<FJsonValue>& V : N->GetArrayField(TEXT("spots")))
	{
		const TSharedPtr<FJsonObject> O = V->AsObject(); FString C; O->TryGetStringField(TEXT("if"), C);
		FStorySpot Sp; Sp.Id = O->GetStringField(TEXT("id")); O->TryGetStringField(TEXT("label"), Sp.Label);
		bool bOnce = true; O->TryGetBoolField(TEXT("once"), bOnce); Sp.bOnce = bOnce;
		if (Sp.bOnce && SVar(TEXT("seen.") + Sp.Id)) continue;
		if (!StoryCond(C)) continue;
		Sp.Pos = StoryAt(O->GetStringField(TEXT("at")));
		if (Sp.Pos.IsZero() && Player) Sp.Pos = PlayerLoc() + FVector(200.f * (HubSpots.Num() + 1), 0, 0);   // placeholder until staged
		const FJArr* Do; if (O->TryGetArrayField(TEXT("do"), Do)) Sp.Do = *Do;
		HubSpots.Add(Sp);
	}
	if (StoryCond(Exit) && !Exit.IsEmpty()) { HubSpots.Reset(); bHub = false; UI->Objective.Empty(); return true; }
	if (!HubSpots.Num()) { SLOG("[PBXSTORY] ERROR hub in %s has no spots left and exit '%s' is false", *StoryScene, *Exit); HubSpots.Reset(); bHub = false; return true; }
	bHub = true; StoryCamRelease();
	if (bAuto) QDo([this] { if (bHub && HubSpots.Num()) StoryUseSpot(0); });   // autotest: visit the spots in order
	return false;
}

void APBXDirector::StoryUseSpot(int32 i)
{
	if (!HubSpots.IsValidIndex(i)) return;
	const FStorySpot Sp = HubSpots[i];
	if (Sp.bOnce) SVars.Add(TEXT("seen.") + Sp.Id, 1);
	bHub = false; HubSpots.Reset(); UI->Prompt.Empty();
	SLOG("[PBXSTORY] spot %s:%s", *StoryScene, *Sp.Id);
	StoryPush(&Sp.Do); QStoryPump();
}

// ---------------------------------------------------------------- the end of an episode: "Your Codex"
void APBXDirector::StoryEndEpisode()
{
	SLOG("[PBXSTORY] END %s", *StoryEp); StoryCamRelease();
	TArray<FPBXOption> Pages; TArray<FString> Lines;
	const TArray<TSharedPtr<FJsonValue>>* Codex;
	if (StoryData->TryGetArrayField(TEXT("codex"), Codex))
		for (const TSharedPtr<FJsonValue>& V : *Codex)
		{
			const TSharedPtr<FJsonObject> P = V->AsObject(); FPBXOption X; X.Title = P->GetStringField(TEXT("title")); X.Sub = TEXT("unwritten");
			for (const TSharedPtr<FJsonValue>& W : P->GetArrayField(TEXT("pages")))
			{
				const TArray<TSharedPtr<FJsonValue>>& Pr = W->AsArray();
				if (Pr.Num() >= 2 && StoryCond(Pr[0]->AsString())) { X.Sub = Pr[1]->AsString(); break; }
			}
			Lines.Add(X.Title + TEXT(": ") + X.Sub);
			X.Title = X.Title + TEXT("  —  ") + X.Sub; X.Sub.Empty();   // one line per page: nine pages must fit on one screen
			Pages.Add(X);
		}
	for (const FString& L : Lines) SLOG("[PBXSTORY] codex %s", *L);
	UI->BigT = 0.f;
	FPBXOption Back; Back.Title = TEXT("Close the book"); Pages.Add(Back);
	if (Game && Game->State) { Game->State->StoryScene = TEXT("__end"); Game->State->StoryVars = SVars; if (!bAuto) SaveNow(false); }
	if (bAuto) { Shot(TEXT("st_your_codex")); QWait(1.5f); QDo([this] { bStoryMode = false; FPlatformMisc::RequestExit(false); }); }
	OpenChoice(TEXT("YOUR CODEX"), TEXT("The pages your choices wrote."), Pages, false, [this, N = Pages.Num()](int32 i)
	{
		if (i == N - 1) { CloseChoice(); bStoryMode = false; ToTitle(); }
	});
}

// ---------------------------------------------------------------- story audio (voices, music, ambience: loose WAVs)
float APBXDirector::StoryVoicePlay(const FString& Id)
{
	if (StoryVoice) { StoryVoice->Stop(); StoryVoice = nullptr; }
	float Secs = 0.f;
	if (USoundWaveProcedural* W = PBXAudio::Load(this, TEXT("vo"), Id, false, &Secs)) { StoryVoice = UGameplayStatics::SpawnSound2D(this, W, 1.0f, 1.f, 0.f, nullptr, false, false); FilmCue(TEXT("vo"), Id, 1.f); }
	else SLOG("[PBXSTORY] voice missing %s", *Id);
	StoryLineSecs = Secs;
	return Secs;
}

void APBXDirector::StoryLoop(TObjectPtr<UAudioComponent>& Comp, FString& Cur, const TCHAR* Kind, const FString& Name, float Vol, float Fade)
{
	if (Cur == Name && Comp) return;
	if (Comp) { Comp->FadeOut(Fade, 0.f); Comp = nullptr; FilmCue(FString(Kind) + TEXT("_out"), Cur, 0.f, FString::Printf(TEXT("\"fade\":%.2f"), Fade)); }
	Cur = Name;
	if (Name.IsEmpty()) return;
	if (USoundWaveProcedural* W = PBXAudio::Load(this, Kind, Name, true))
	{
		Comp = UGameplayStatics::SpawnSound2D(this, W, Vol, 1.f, 0.f, nullptr, false, false);
		if (Comp) Comp->FadeIn(Fade, Vol);
		FilmCue(Kind, Name, Vol, FString::Printf(TEXT("\"fade\":%.2f"), Fade));
	}
	else SLOG("[PBXSTORY] %s missing %s", Kind, *Name);
}

void APBXDirector::StoryAudioStop()
{
	if (StoryVoice) { StoryVoice->Stop(); StoryVoice = nullptr; }
	if (StoryMusic) { StoryMusic->FadeOut(1.f, 0.f); StoryMusic = nullptr; }
	if (StoryAmb) { StoryAmb->FadeOut(1.f, 0.f); StoryAmb = nullptr; }
	StoryMusicName.Empty(); StoryAmbName.Empty();
}

// ---------------------------------------------------------------- cinematic dialogue cameras
AActor* APBXDirector::StoryActor(const FString& Who) const
{
	if (Who == TEXT("hero")) return Player;
	FString Id = Who; const TSharedPtr<FJsonObject>* Cast_;
	if (StoryData.IsValid() && StoryData->TryGetObjectField(TEXT("cast"), Cast_)) { const TSharedPtr<FJsonObject>* C; if ((*Cast_)->TryGetObjectField(Who, C)) (*C)->TryGetStringField(TEXT("npc"), Id); }
	if (const TObjectPtr<APBXNPC>* N = NPCs.Find(FName(*Id))) if (*N && !(*N)->IsHidden()) return *N;
	return nullptr;
}

FVector APBXDirector::HeadOf(AActor* A) const
{
	// MetaHumans: from the floor and the character's height (the head socket can be stale right after a teleport, before
	// the pose ticks — Gus's close-ups framed his chest)
	if (const APBXCharacterBase* P = Cast<APBXCharacterBase>(A)) if (P->bMetaHuman && P->GetCapsuleComponent())
	{
		const float Floor = P->GetActorLocation().Z - P->GetCapsuleComponent()->GetScaledCapsuleHalfHeight();
		return FVector(P->GetActorLocation().X, P->GetActorLocation().Y, Floor + P->MHHeight * .925f);
	}
	if (ACharacter* C = Cast<ACharacter>(A)) if (C->GetMesh() && C->GetMesh()->DoesSocketExist(TEXT("head"))) return C->GetMesh()->GetSocketLocation(TEXT("head")) + FVector(0, 0, 4);
	return A ? A->GetActorLocation() + FVector(0, 0, 70) : FVector::ZeroVector;
}

void APBXDirector::StoryShot(const FString& Who)
{
	if (!Cam || !Player || Who == TEXT("narrator") || Who == TEXT("codex") || Who == TEXT("spark")) return;
	AActor* Spk = StoryActor(Who);
	AActor* Lis = nullptr;
	if (Spk == Player) Lis = ShotOther.Get();
	else if (Spk) { Lis = Player; ShotOther = Spk; }
	if (!Spk || !Lis || FVector::Dist(Spk->GetActorLocation(), Lis->GetActorLocation()) > 2200.f) return;   // nobody to frame: keep the shot
	const FVector Hs = HeadOf(Spk), Hl = HeadOf(Lis);
	FVector Dir = (Hs - Hl).GetSafeNormal2D(); if (Dir.IsNearlyZero()) Dir = FVector(1, 0, 0);
	// the two face each other (people turn to whoever speaks)
	if (APBXNPC* N = Cast<APBXNPC>(Spk == Player ? Lis : Spk)) N->SetActorRotation(FRotator(0, (-Dir * (Spk == Player ? -1.f : 1.f)).Rotation().Yaw, 0));
	Player->SetActorRotation(FRotator(0, ((Spk == Player ? Lis : Spk)->GetActorLocation() - Player->GetActorLocation()).GetSafeNormal2D().Rotation().Yaw, 0));
	if (APBXCharacterBase* C = Cast<APBXCharacterBase>(Spk)) C->SetLookAt(Hl);
	if (APBXCharacterBase* C = Cast<APBXCharacterBase>(Lis)) C->SetLookAt(Hs);
	for (TActorIterator<APBXNPC> It(GetWorld()); It; ++It)   // bystanders within earshot glance at the speaker
		if (*It != Spk && *It != Lis && FVector::Dist(It->GetActorLocation(), Spk->GetActorLocation()) < 900.f) It->SetLookAt(Hs);
	const int32 K0 = ShotN++ % 4;
	// Telltale-style coverage chosen by SEARCH, not from 8 fixed spots (owner 2026-11-08: "everything placed right, looking
	// right"; in the s1 market every fixed spot was inside a stall). Around the speaker's face: 7 azimuths in front of the
	// face × 4 distances × 2 heights. A spot counts only if the lens is not inside anything and fat rays to the eyes, the
	// chin and both cheeks are free; then shot grammar scores it: the line's shot type (OTS / CU / two-shot), ~20-40 deg off
	// the eyeline, the 180-degree rule (same side of the line as the last shot of this pair), the listener's shoulder in
	// frame for OTS, not too close.
	if (ShotPairA.Get() != Spk && ShotPairA.Get() != Lis) { ShotSide = 0.f; }
	ShotPairA = Spk; ShotPairB = Lis;
	const FVector Mid = (Hs + Hl) * .5f;
	FHitResult Hit; FCollisionQueryParams Q(SCENE_QUERY_STAT(StoryCam), false); Q.AddIgnoredActor(Spk); Q.AddIgnoredActor(Lis); Q.AddIgnoredActor(Player);
	const FCollisionShape Ball = FCollisionShape::MakeSphere(12.f), Body = FCollisionShape::MakeSphere(22.f);
	auto Free = [&](const FVector& A, const FVector& B) { return !GetWorld()->SweepSingleByChannel(Hit, A, B, FQuat::Identity, ECC_Camera, Ball, Q); };
	auto Inside = [&](const FVector& P) { return GetWorld()->OverlapAnyTestByChannel(P, FQuat::Identity, ECC_Camera, Body, Q); };
	const FVector FaceDir = -Dir;   // the speaker faces the listener: -Dir points from the speaker toward the listener
	const FVector FaceRight = FVector::CrossProduct(FVector::UpVector, FaceDir);
	FVector Eye = Hl - Dir * 150.f, Look = Hs; float Fov = 36.f; float Best = -1e9f; int32 Tried = 0, Ok = 0;
	static const float Az[] = { 0.f, 22.f, -22.f, 38.f, -38.f, 58.f, -58.f };
	static const float Dist[] = { 130.f, 165.f, 210.f, 280.f };
	static const float Up[] = { 2.f, 14.f };
	const bool bWantOTS = (K0 == 0 || K0 == 2), bWantTwo = (K0 == 3);
	for (float az : Az) for (float d : Dist) for (float up : Up)
	{
		Tried++;
		const FVector V = FaceDir.RotateAngleAxis(az, FVector::UpVector);
		const FVector E = Hs + V * d + FVector(0, 0, up);
		if (Inside(E)) continue;
		const FVector Cheek = FaceRight * 9.f;
		if (!Free(E, Hs) || !Free(E, Hs + Cheek) || !Free(E, Hs - Cheek) || !Free(E, Hs - FVector(0, 0, 14))) continue;
		Ok++;
		float Score = 0.f;
		const float Off = FMath::Abs(az);
		Score -= FMath::Abs(Off - 28.f) * .04f;                                       // a little off the eyeline reads best
		const float Side = FMath::Sign(FVector::DotProduct(E - Mid, FaceRight * (Spk == Player ? 1.f : -1.f)));
		if (ShotSide != 0.f && Side != ShotSide) Score -= 3.f;                        // 180-degree rule
		if (bWantOTS) { Score -= FMath::Abs(d - 210.f) * .01f; if (FVector::Dist2D(E, Hl) < 140.f && Free(E, Hl - FVector(0, 0, 20))) Score += 1.5f; }   // the listener's shoulder in frame
		else if (bWantTwo) { Score -= FMath::Abs(d - 280.f) * .01f; if (Free(E, Hl)) Score += 1.f; }
		else Score -= FMath::Abs(d - 140.f) * .012f;                                  // close-up
		if (d < 140.f && Off > 45.f) Score -= 1.f;                                     // no profile close-ups jammed against a wall
		if (Score > Best) { Best = Score; Eye = E; Look = bWantTwo ? FMath::Lerp(Hs, Mid, .45f) : Hs; Fov = bWantTwo ? 42.f : (d < 150.f ? 30.f : 36.f); }
	}
	if (Best > -1e8f) ShotSide = FMath::Sign(FVector::DotProduct(Eye - Mid, FaceRight * (Spk == Player ? 1.f : -1.f)));
	else
	{   // nothing clear at eye level: look down on the face from above the clutter, then straight in front (never closer than 90 cm)
		Look = Hs; Fov = 38.f; Eye = Hs + FaceDir * 150.f + FVector(0, 0, 80.f);
		if (Inside(Eye) || !Free(Eye, Hs))
		{
			Eye = Hs + FaceDir * 140.f;
			if (GetWorld()->SweepSingleByChannel(Hit, Hs, Eye, FQuat::Identity, ECC_Camera, Ball, Q)) Eye = Hs + FaceDir * FMath::Max(90.f, Hit.Distance - 15.f);
		}
	}
	const float Clear = Tried ? float(Ok) / Tried : 0.f;
	SLOG("[PBXSTORY] shot %s K0 %d clear %.2f eye %s look %s Hs %s Hl %s", *Who, K0, Clear, *Eye.ToCompactString(), *Look.ToCompactString(), *Hs.ToCompactString(), *Hl.ToCompactString());
	ShotA = Eye; ShotB = Eye + (Look - Eye).GetSafeNormal() * 22.f; ShotLook = Look; ShotFov = Fov; ShotT = 0.f;
	if (!bStoryCam) { bStoryCam = true; if (APlayerController* PC = GetWorld()->GetFirstPlayerController()) PC->SetViewTarget(Cam); }
	StoryCamTick(0.f);
}

// ---------------------------------------------------------------- acting (owner 2026-11-06: "every scene a real animation, like Telltale")
// Each line: the speaker plays a gesture chosen from what the line says, for as long as the voice lasts, then eases back
// to the idle; the listener sometimes nods or folds the arms. Library = UAL clips retargeted to the MetaHuman body.
void APBXDirector::StoryAct(const FString& Who, const FString& Line, float Secs)
{
	if (Who == TEXT("narrator") || Who == TEXT("codex") || Who == TEXT("spark")) return;
	APBXCharacterBase* Spk = Cast<APBXCharacterBase>(StoryActor(Who)); if (!Spk) return;
	if (APBXCharacterBase* Prev = ActSpk.Get()) if (Prev != Spk) Prev->StopAction(.35f);
	const FString L = Line.TrimStartAndEnd().Replace(TEXT("\""), TEXT(""));
	auto Starts = [&](std::initializer_list<const TCHAR*> W) { for (const TCHAR* w : W) if (L.StartsWith(w, ESearchCase::IgnoreCase)) return true; return false; };
	auto Has = [&](std::initializer_list<const TCHAR*> W) { for (const TCHAR* w : W) if (L.Contains(w, ESearchCase::IgnoreCase)) return true; return false; };
	const TCHAR* Clip = TEXT("Idle_Talking_Loop"); bool bLoop = true;
	const int32 Roll = (ActN++ * 7 + L.Len()) % 10;
	if (Starts({ TEXT("No"), TEXT("Don't"), TEXT("Never"), TEXT("Stop"), TEXT("Not ") }) || Has({ TEXT(" not with you"), TEXT("I wasn't") })) Clip = TEXT("Idle_No_Loop");
	else if (Starts({ TEXT("Yes"), TEXT("Yeah"), TEXT("Fine"), TEXT("Okay"), TEXT("Good"), TEXT("Right") })) { Clip = TEXT("Yes"); bLoop = false; }
	else if (Starts({ TEXT("..."), TEXT("Hm"), TEXT("Well") }) || Roll == 0) Clip = TEXT("Idle_FoldArms_Loop");
	Spk->PlayAction(Clip, bLoop, .25f);
	ActSpk = Spk; ActEnd = GetWorld()->GetTimeSeconds() + FMath::Clamp(Secs, 1.f, 12.f);
	static const bool bFaceShots = FParse::Param(FCommandLine::Get(), TEXT("pbxfaceshots"));
	if (bFaceShots && FaceShots < 8) { FaceShotAt = GetWorld()->GetTimeSeconds() + FMath::Min(1.3, Secs * .4); FaceShotName = FString::Printf(TEXT("face_%02d_%s"), FaceShots++, *Who); }
	// the listener reacts now and then
	if (APBXCharacterBase* Lis = Cast<APBXCharacterBase>(Spk == Player ? ShotOther.Get() : (AActor*)Player))
	{
		if (L.EndsWith(TEXT("?")) && Roll < 4) Lis->PlayAction(TEXT("Yes"), false, .3f);
		else if (Roll == 7) Lis->PlayAction(TEXT("Idle_FoldArms_Loop"), true, .4f);
		else if (Lis != Spk) Lis->StopAction(.4f);
	}
}

void APBXDirector::StoryActTick()
{
	if (FaceShotAt > 0.0 && GetWorld()->GetTimeSeconds() >= FaceShotAt) { FaceShotAt = 0.0; Shot(FaceShotName); }
	if (APBXCharacterBase* A = ActSpk.Get()) if (GetWorld()->GetTimeSeconds() >= ActEnd) { A->StopAction(.45f); ActSpk = nullptr; }
}

static TWeakObjectPtr<UPointLightComponent> GFaceFill;
void APBXDirector::StoryCamTick(float Dt)
{
	StoryActTick();
	if (!bStoryCam || !Cam) { if (GFaceFill.IsValid()) GFaceFill->SetVisibility(false); if (UI->Letterbox > 0.f && !Busy()) UI->Letterbox = FMath::Max(0.f, UI->Letterbox - Dt * 3.f); return; }
	if (!GFaceFill.IsValid())
	{   // a soft fill riding with the lens, like a Telltale face light: faces never go black against a bright sky or a dark room
		UPointLightComponent* L = NewObject<UPointLightComponent>(Cam, TEXT("PBXFaceFill"));
		L->SetupAttachment(Cam->GetRootComponent()); L->RegisterComponent();
		L->SetIntensityUnits(ELightUnits::Candelas); L->SetIntensity(9.f); L->SetAttenuationRadius(420.f); L->SetSourceRadius(45.f);
		L->SetCastShadows(false); L->SetSpecularScale(.25f); L->SetLightColor(FLinearColor(1.f, .92f, .82f));
		L->SetRelativeLocation(FVector(-15.f, 60.f, 28.f)); GFaceFill = L;
	}
	GFaceFill->SetVisibility(true);
	ShotT += Dt; const float a = FMath::Clamp(ShotT / 6.f, 0.f, 1.f);
	const FVector E = FMath::Lerp(ShotA, ShotB, a * a * (3.f - 2.f * a));   // a slow push-in over each line
	Cam->SetActorLocationAndRotation(E, (ShotLook - E).Rotation()); Cam->GetCameraComponent()->SetFieldOfView(ShotFov);
	UI->Letterbox = FMath::Min(1.f, UI->Letterbox + Dt * 3.f);
}

bool APBXDirector::StoryFilm(const FString& Id)
{
	static const bool bNoFilm = FParse::Param(FCommandLine::Get(), TEXT("pbxnofilm"));
	if (bNoFilm || Id.IsEmpty()) { StoryFilmStop(); return false; }
	const FString File = FPaths::ConvertRelativePathToFull(FPaths::ProjectContentDir() / TEXT("Movies") / StoryEp / (Id + TEXT(".mp4")));
	if (!FPaths::FileExists(File)) { FilmMissed++; StoryFilmStop(); return false; }
	if (!FilmPlayer)
	{
		FilmPlayer = NewObject<UMediaPlayer>(this); FilmPlayer->PlayOnOpen = true; FilmPlayer->SetLooping(false);
		FilmTex = NewObject<UMediaTexture>(this); FilmTex->AutoClear = false; FilmTex->SetMediaPlayer(FilmPlayer); FilmTex->UpdateResource();   // keep the last frame: no black flash between beats
		FilmSrc = NewObject<UFileMediaSource>(this);
		UI->FilmBrush = MakeShared<FSlateBrush>(); UI->FilmBrush->SetResourceObject(FilmTex); UI->FilmBrush->ImageSize = FVector2D(1920, 1080);
	}
	FilmSrc->SetFilePath(File); FilmPlayer->OpenSource(FilmSrc);
	UI->FilmA = 1.f; UI->Letterbox = 0.f; bFilmOn = true; FilmPlayed++;
	SLOG("[PBXSTORY] film %s", *Id);
	return true;
}

void APBXDirector::StoryFilmStop()
{
	if (!bFilmOn) return;
	bFilmOn = false; UI->FilmA = 0.f;
	if (FilmPlayer) FilmPlayer->Close();
}

void APBXDirector::StoryCamRelease()
{
	StoryFilmStop();
	for (TActorIterator<APBXCharacterBase> It(GetWorld()); It; ++It) It->SetLookAt(FVector::ZeroVector, false);
	if (APBXCharacterBase* A = ActSpk.Get()) A->StopAction(.4f); ActSpk = nullptr;
	if (!bStoryCam) return;
	bStoryCam = false;
	if (APlayerController* PC = GetWorld()->GetFirstPlayerController()) if (Player) { PC->SetViewTarget(Player); Player->SnapCamera(); }
	if (Cam) Cam->GetCameraComponent()->SetFieldOfView(70.f);
}

// ---------------------------------------------------------------- hub marks: soft ink dots over what you can look at
void APBXDirector::StoryMarksTick()
{
	UI->Marks.Reset();
	if (!bHub || UI->Mode != EPBXUIMode::Explore || !Player) return;
	APlayerController* PC = GetWorld()->GetFirstPlayerController(); if (!PC) return;
	const float Scale = FMath::Max(.1f, UWidgetLayoutLibrary::GetViewportScale(this));
	int32 VX = 0, VY = 0; PC->GetViewportSize(VX, VY); const FVector2D View = FVector2D(VX, VY) / Scale;
	const FVector P = PlayerLoc();
	for (int32 i = 0; i < HubSpots.Num(); i++)
	{
		const FVector W = HubSpots[i].Pos + FVector(0, 0, 120.f);
		const float D = FVector::Dist(P, W);
		FPBXUIModel::FMark K; K.A = FMath::Clamp(1.f - (D - 400.f) / 3200.f, .25f, 1.f) * (NearKind == EKind::Story && NearIndex == i ? .35f : .8f);   // fades out when you stand on it (the [E] prompt takes over)
		FVector2D S; const bool bOn = PC->ProjectWorldLocationToScreen(W, S, true);
		S /= Scale;
		const bool bInside = bOn && S.X > 30 && S.Y > 30 && S.X < View.X - 30 && S.Y < View.Y - 30;
		if (!bInside)   // off screen: a smaller dot pinned to the edge, in the direction to turn
		{
			const FVector L = PC->PlayerCameraManager->GetCameraRotation().UnrotateVector(W - PC->PlayerCameraManager->GetCameraLocation());
			FVector2D Dir2(L.Y, -L.Z); if (Dir2.IsNearlyZero()) Dir2 = FVector2D(1, 0); Dir2.Normalize();
			const FVector2D C = View * .5f; const float T = FMath::Min((View.X * .5f - 40.f) / FMath::Max(.01f, FMath::Abs(Dir2.X)), (View.Y * .5f - 40.f) / FMath::Max(.01f, FMath::Abs(Dir2.Y)));
			S = C + Dir2 * T; K.bEdge = true; K.A *= .55f;
		}
		K.P = S; UI->Marks.Add(K);
	}
}

// ---------------------------------------------------------------- prologue cards
void APBXDirector::QCard(const FString& Text, const FString& Sub, const FString& Vo)
{
	TSharedPtr<float> Len = MakeShared<float>(-1.f);
	Q([this, Text, Sub, Vo, Len](float T)
	{
		if (*Len < 0.f) { *Len = FMath::Max(3.5f, StoryVoicePlay(Vo) + 1.2f); UI->CardText = Text; UI->CardSub = Sub; bConfirm = false; }
		const float Out = *Len;
		UI->CardA = FMath::Clamp(FMath::Min(T * 1.6f, (Out - T) * 1.6f + 1.f), 0.f, 1.f);
		if ((bConfirm && T > .4f) || T >= Out + .6f) { bConfirm = false; UI->CardA = 0.f; if (StoryVoice) StoryVoice->FadeOut(.3f, 0.f); return true; }
		return false;
	});
}
